#!/usr/bin/env python3
# -*- coding: utf-8 -*-

from __future__ import annotations

import argparse
import base64
import json
import subprocess
import sys
from pathlib import Path

MANIFEST_VERSION = "2026-04-29-band-engineering-bootstrap-v6"
FILES_B64 = {
  "skills/band-align-plot/SKILL.md": "",
  "skills/band-align-plot/references/input-schema.md": "",
  "skills/band-align-plot/scripts/build_config.py": "",
  "skills/band-align-plot/scripts/render_band_align.py": "",
  "skills/band-align-plot/scripts/install_bapt.py": "",
  "skills/band-diagram-calc/SKILL.md": "",
  "skills/band-diagram-calc/references/input-schema.md": "",
  "skills/band-diagram-calc/assets/presets/materials.json": "",
  "skills/band-diagram-calc/scripts/install_eq_band_diagram.py": "",
  "skills/band-diagram-calc/scripts/solve_band_diagram.py": "",
  "skills/interface-band-offset/SKILL.md": "",
  "skills/interface-band-offset/references/input-schema.md": "",
  "skills/interface-band-offset/references/bulk-slab-interface-template.json": "",
  "skills/interface-band-offset/references/example-slab-based-minimal.json": "",
  "skills/interface-band-offset/references/example-explicit-interface-minimal.json": "",
  "skills/interface-band-offset/references/example-slab-plus-explicit-minimal.json": "",
  "skills/interface-band-offset/references/minimal-examples.md": "",
  "skills/interface-band-offset/scripts/install_intermat.py": "",
  "skills/interface-band-offset/scripts/run_band_offset_analysis.py": ""
}
INSTALLERS = [
    "skills/band-align-plot/scripts/install_bapt.py",
    "skills/band-diagram-calc/scripts/install_eq_band_diagram.py",
    "skills/interface-band-offset/scripts/install_intermat.py",
]


def _decode_manifest() -> dict[str, str]:
    return {path: base64.b64decode(data.encode("ascii")).decode("utf-8") for path, data in FILES_B64.items()}


def write_files(base_dir: Path, overwrite: bool = True) -> list[str]:
    written = []
    for rel_path, content in _decode_manifest().items():
        target = base_dir / rel_path
        target.parent.mkdir(parents=True, exist_ok=True)
        if target.exists() and not overwrite:
            continue
        target.write_text(content, encoding="utf-8")
        written.append(str(target))
    return written


def run_installers(base_dir: Path) -> list[dict[str, object]]:
    results = []
    for installer in INSTALLERS:
        installer_path = base_dir / installer
        proc = subprocess.run([sys.executable, str(installer_path)], cwd=str(base_dir), capture_output=True, text=True, check=False)
        results.append({
            "installer": installer,
            "returncode": proc.returncode,
            "stdout": proc.stdout.strip(),
            "stderr": proc.stderr.strip(),
        })
    return results


def main() -> None:
    parser = argparse.ArgumentParser(description="Bootstrap the three band-engineering skills into a workspace.")
    parser.add_argument("--base-dir", default=".", help="Workspace root where the skills/ tree should be created.")
    parser.add_argument("--skip-existing", action="store_true", help="Do not overwrite files that already exist.")
    parser.add_argument("--install-backends", action="store_true", help="After writing files, run the three local installer scripts.")
    args = parser.parse_args()

    base_dir = Path(args.base_dir).resolve()
    written = write_files(base_dir=base_dir, overwrite=not args.skip_existing)

    result = {
        "status": "ok",
        "manifest_version": MANIFEST_VERSION,
        "base_dir": str(base_dir),
        "written_count": len(written),
        "written_files": written,
        "installers_run": False,
        "installer_results": [],
    }

    if args.install_backends:
        result["installers_run"] = True
        result["installer_results"] = run_installers(base_dir=base_dir)
        if any(item["returncode"] != 0 for item in result["installer_results"]):
            result["status"] = "warning"

    print(json.dumps(result, indent=2, ensure_ascii=False))


if __name__ == "__main__":
    main()
